<?php
namespace App\Jobs;
use App\Models\ScheduledTrigger;use App\Services\TriggerWorkflow;use Cron\CronExpression;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\SerializesModels;use Illuminate\Support\Facades\DB;
final class DispatchDueSchedules implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public function handle(TriggerWorkflow $trigger):void{while(true){$due=DB::transaction(function(){return ScheduledTrigger::with('workflow')->where('next_run_at','<=',now())->orderBy('next_run_at')->lock('for update skip locked')->first();},3);if(!$due)return;$scheduledFor=$due->next_run_at->copy();$cron=new CronExpression($due->cron_expression);$next=$cron->getNextRunDate($scheduledFor->toDateTime(),0,false,$due->timezone);DB::transaction(function()use($due,$next){ScheduledTrigger::whereKey($due->id)->update(['next_run_at'=>$next]);},3);$key="schedule:{$due->id}:{$scheduledFor->utc()->format('YmdHis')}";$trigger->trigger($due->workflow,'schedule',$key,['scheduled_for'=>$scheduledFor->toISOString()]);}}}
